function reviseDraftHourly(id){const source=db.bulletins.find(d=>d.id===id);if(!source)return;try{const v=BulletinRevision.hourlyVariables(source),result=PayrollTest.calculate(engineInput(v));const existing=db.bulletins.find(d=>d.revises===id&&d.revisionMethod==='hourly');if(existing){$('#modal').close();showDraft(existing.id);return;}const doc={...structuredClone(source),id:crypto.randomUUID(),createdAt:new Date().toISOString(),engine:PayrollTest.version,revises:id,revisionMethod:'hourly',variables:v,result,issues:[...source.issues,'Recalcul horaire demandé : contrôler les assiettes manuelles, le net imposable, le net social et les cumuls.']};db.bulletins.push(doc);if(!save()){db.bulletins.pop();return;}$('#modal').close();render();showDraft(doc.id);toast('Nouvelle version horaire enregistrée ; bulletin précédent conservé.');}catch(e){toast(e.message);}}
const beforeRevisionShowDraft=showDraft;
showDraft=function(id){beforeRevisionShowDraft(id);const d=db.bulletins.find(b=>b.id===id),tools=$('#form .no-print .tools');if(!d||!tools)return;if(d.revises){const p=document.createElement('p');p.className='notice no-print';p.textContent='Version recalculée en heures rémunérées. L’original est conservé dans l’historique.';tools.after(p);return;}try{const v=BulletinRevision.hourlyVariables(d);const button=document.createElement('button');button.type='button';button.className='btn';button.textContent='Recalculer '+Number(v.hours)+' h × '+euroFmt(v.hourlyRate)+' = '+euroFmt(v.base);button.onclick=()=>reviseDraftHourly(id);tools.prepend(button);const note=document.createElement('p');note.className='notice no-print';note.textContent='Ce bulletin enregistré utilise le prorata mensuel. Le bouton crée une version au calcul horaire demandé, en conservant la date d’entrée et le bulletin original.';tools.after(note);}catch{}};
